with cleaned as (select id, browser, started_at, coalesce(country, 'Unknown') as country_filled, coalesce(browser, 'NONE') as resolved_browser from sessions where started_at > timestamp '2023-07-08 03:00:00') select id, browser, started_at, country_filled, row_number() over w_part as row_seq, row_number() over (partition by browser order by started_at asc, id asc) as row_seq_2, first_value(browser, true) over (order by started_at asc, id asc rows between unbounded preceding and current row) as first_known_browser from cleaned where started_at < '2024-03-01' window w_part as (partition by browser order by started_at desc, id asc)
